import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class ManyToMany {
    public static void main(String[] args) {
        Map<Integer, Set<Integer>> enrollment = new HashMap<>();
        enrollment.computeIfAbsent(1, k -> new HashSet<>()).add(10);
        enrollment.computeIfAbsent(1, k -> new HashSet<>()).add(20);
        enrollment.computeIfAbsent(2, k -> new HashSet<>()).add(10);
        enrollment.computeIfAbsent(1, k -> new HashSet<>()).add(10);
        int total = 0;
        for (Set<Integer> courses : enrollment.values()) {
            total += courses.size();
        }
        System.out.println(total);
    }
}

