public class ScanCount {
    static int linear(int[] keys, int target) {
        int comparisons = 0;
        for (int key : keys) {
            comparisons++;
            if (key == target) {
                break;
            }
        }
        return comparisons;
    }

    public static void main(String[] args) {
        int[] keys = {5, 10, 15, 20, 25, 30, 35, 40};
        System.out.println(linear(keys, 35));
    }
}

